import{_ as i,l as r,o as e,c as o,v as l,p as s,x as t,d as E,i as d,S as m}from"./chunks/framework.InCnrqk-.js";const f=JSON.parse('{"title":"知识注入的限度","description":"","frontmatter":{"title":"知识注入的限度","date":"2026-09-08T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/knowledge-injection-limits.md","filePath":"llm/knowledge-injection-limits.md","lastUpdated":1789023840000}'),h={name:"llm/knowledge-injection-limits.md"};function p(c,a,A,B,u,T){const n=r("Mermaid");return e(),o("div",null,[a[1]||(a[1]=l('<h1 id="知识注入的限度" tabindex="-1">知识注入的限度 <a class="header-anchor" href="#知识注入的限度" aria-label="Permalink to &quot;知识注入的限度&quot;">​</a></h1><div class="epigraph"><p>微调会让模型更愿意陈述训练里见过的新事实，也会让它在没见过的新事实上更敢幻觉；注入不是把条目写入可靠词典。</p><footer>—— Gekhman 等，Does Fine-Tuning LLMs on New Knowledge Encourage Hallucinations?（ACL 2024）；对照 Berglund 等反向诅咒、ROME 的键不对称</footer></div><p><a href="/llm/rome-memit">ROME / MEMIT</a>能改已有槽里的客体。产品常想做的另一件事是<strong>灌入原本没有的知识</strong>：新法规、新 API、内部人名。做法往往是把条目写成指令对再 SFT。Gekhman 等人 2024 年的实验表明：模型对「预训练里已有的事实」微调很听话；对「预训练没有的新事实」，SFT 既难真正学会，又会抬高在其它未知问题上的幻觉率。本课写这条限度。下一课转向对偶操作：遗忘。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p><a href="/llm/lima">LIMA</a> 与<a href="/llm/lora-intrinsic-rank">内在秩</a>都暗示：后训练擅长改接口，不擅长长新世界模型。知识注入却假设 SFT 能把 \\((s,r,o)\\) 写成可检索的权重。若 \\(s\\) 在预训练里没有稳定键（ROME 意义下），<a href="/llm/response-only-loss">仅回复损失</a>只会让模型在训练提示的措辞下背 \\(o\\)；换一种问法就回到先验，或编一个同样自信的 \\(o&#39;\\)。</p><p>Gekhman 等人把例子分成模型已知与未知，再微调未知事实，测量：未知事实的掌握、以及无关未知问题上的幻觉。结果支持「新知识微调鼓励幻觉」：模型学会了「对没把握的题也要像示范那样给出具体答案」。</p><h3 id="反向诅咒是键不对称的生成版" tabindex="-1">反向诅咒是键不对称的生成版 <a class="header-anchor" href="#反向诅咒是键不对称的生成版" aria-label="Permalink to &quot;反向诅咒是键不对称的生成版&quot;">​</a></h3><p>Berglund 等人的反向诅咒：用「A 是 B」训练，模型不会自动回答「B 是谁」。这与 ROME 里反向提示不共享键一致。注入一条正向句，不等于注入一张无向知识图。关系抽取式产品若假设对称，会在反向查询上静默失败。</p><p><span class="marginnote">Ovadia 等人比较微调与检索：时效知识更适合索引。本课不展开 RAG 实现，只把「不要用 SFT 当知识库」当作限度。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>先探针：这条知识是否已在基座补全里以某种措辞出现。已有则用 ROME/MEMIT 或小学习率校正，而不是大 SFT。没有则优先检索；若必须内化，用多样释义、正反向、多跳模板同时监督，并保留大量已知事实回放，抑制「未知→随便编」的接口漂移。学习率按<a href="/llm/lora-vs-full-lr">全参要小</a>；<a href="/llm/lora">LoRA</a> 更难写入新键，表现为只在训练句式上对。</p><p><a href="/llm/chat-template">chat template</a> 下，把知识写进系统提示不是注入权重，是上下文条件；上下文消失则知识消失。不要把长系统提示的成功当成注入成功。</p>',12)),(e(),s(m,null,{default:t(()=>[d(n,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20Q%5B%22%E6%96%B0%E6%9D%A1%E7%9B%AE%22%5D%20--%3E%20P%5B%22%E5%9F%BA%E5%BA%A7%E6%98%AF%E5%90%A6%E5%B7%B2%E6%9C%89%E9%94%AE%22%5D%0A%20%20P%20--%3E%20E%5B%22%E6%9C%89%EF%BC%9A%E5%AE%9A%E4%BD%8D%E7%BC%96%E8%BE%91%22%5D%0A%20%20P%20--%3E%20R%5B%22%E6%97%A0%EF%BC%9A%E6%A3%80%E7%B4%A2%E6%88%96%E5%A4%9A%E6%A0%B7%E7%9B%91%E7%9D%A3%20%2B%20%E5%9B%9E%E6%94%BE%22%5D%0A%20%20R%20--%3E%20H%5B%22%E7%9B%91%E6%8E%A7%E6%97%A0%E5%85%B3%E9%A2%98%E5%B9%BB%E8%A7%89%22%5D%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[E(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=l('<p>评测必须含：训练措辞、释义、反向、无关未知、已知事实保持。只报训练句准确率，会选出背诵器。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>SFT 强化的是「在此类提示后给出具体完成」的策略。示范都是有答案的，模型把「具体完成」泛化到无槽可取的提示上，幻觉上升。已知事实上，键已存在，SFT 主要校准措辞，幻觉不必升。这与 NEFTune 减少背诵不同：注入任务偏偏要精确记忆，噪声与多样性的权衡更紧。</p><p>编辑改指定 \\(Wk=v\\)，不训练「要答得具体」这一接口策略，因此对无关未知的伤害通常小于灌表 SFT。但编辑不创造新键：主体从未出现过，没有槽可写。限度是结构的，不是超参没扫好。</p><p><span class="marginnote">领域 DAPT 用全文 LM 把术语推进先验，比对话表注入更接近「长出键」。仍不保证事实图对称，只是降低完全 OOV。</span></p><h2 id="边界与工程取舍" tabindex="-1">边界与工程取舍 <a class="header-anchor" href="#边界与工程取舍" aria-label="Permalink to &quot;边界与工程取舍&quot;">​</a></h2><p>内部知识有权限与过期问题：写入权重难以按文档撤回，这直接接到<a href="/llm/machine-unlearning">机器遗忘</a>。能检索就检索。必须内化的流程性知识（如何填内部工单）属于技能，不是三元组，SFT 更合适。评测幻觉要用封闭题 +「我不知道」许可，否则模型被训练成永远具体。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>预训练已有键的事实可编辑或轻 SFT；没有键的新事实难以内化。</li><li>对新事实做 SFT 会强化「未知也具体作答」，抬高无关幻觉。</li><li>反向与释义不自动成立，需单独监督或接受不对称。</li><li>系统提示是上下文，不是注入。</li><li>时效与可撤回知识用检索；SFT 留给技能与接口。</li><li>出处：Gekhman 等，ACL 2024；Berglund 等，反向诅咒；Meng 等，ROME/MEMIT。</li></ul>',9))])}const S=i(h,[["render",p]]);export{f as __pageData,S as default};
